import AppKit

// Renders Resources/AppIcon.icns. Run via: swift Tools/makeicon.swift <out.icns>
//
// The Jarvis orb: a sphere sketched out of dots — latitude rings on a tilted axis
// plus the silhouette — white on transparent, so the icon reads the same on a light
// or dark Dock. Drawn rather than drafted in an editor because it has to be
// regenerated by build.sh on any machine with nothing but the Command Line Tools.

private let tilt: CGFloat = 22 * .pi / 180

func render(size: Int) -> Data {
    let s = CGFloat(size)
    let scale = s / 1024.0
    let cs = CGColorSpaceCreateDeviceRGB()
    let ctx = CGContext(data: nil, width: size, height: size, bitsPerComponent: 8,
                        bytesPerRow: 0, space: cs,
                        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
    ctx.setAllowsAntialiasing(true)
    ctx.interpolationQuality = .high

    let cx = s / 2, cy = s / 2
    let R = 380 * scale
    // Below 64 px the full dot pattern turns to mush, so the small sizes get a
    // deliberately coarser orb instead of a faithful one.
    let detailed = size >= 64
    let base = (detailed ? 13.0 : 21.0) * scale

    func dot(_ x: CGFloat, _ y: CGFloat, _ r: CGFloat, _ alpha: CGFloat) {
        ctx.setFillColor(CGColor(red: 1, green: 1, blue: 1, alpha: alpha))
        ctx.fillEllipse(in: CGRect(x: x - r, y: y - r, width: r * 2, height: r * 2))
    }

    struct Point { let x: CGFloat; let y: CGFloat; let depth: CGFloat }
    var points: [Point] = []

    let latitudes: [CGFloat] = detailed
        ? [-80, -60, -40, -20, 0, 20, 40, 60, 80]
        : [-45, 0, 45]
    let equatorDots = detailed ? 30 : 12

    for latDeg in latitudes {
        let phi = latDeg * .pi / 180
        let ringR = R * cos(phi)
        let ringY = R * sin(phi)
        let count = max(detailed ? 8 : 5, Int((CGFloat(equatorDots) * cos(phi)).rounded()))
        for i in 0..<count {
            let theta = CGFloat(i) / CGFloat(count) * .pi * 2
            let x = ringR * cos(theta)
            let y = ringY
            let z = ringR * sin(theta)
            // Tilt the polar axis toward the viewer so the rings project as
            // ellipses; with an upright axis they collapse into flat lines.
            let y2 = y * cos(tilt) - z * sin(tilt)
            let z2 = y * sin(tilt) + z * cos(tilt)
            points.append(Point(x: cx + x, y: cy + y2, depth: z2 / R))
        }
    }

    // Silhouette: the great circle in the view plane, which is what makes the
    // scattered dots read as one solid ball.
    let rimCount = detailed ? 44 : 16
    for i in 0..<rimCount {
        let a = CGFloat(i) / CGFloat(rimCount) * .pi * 2
        points.append(Point(x: cx + cos(a) * R, y: cy + sin(a) * R, depth: 0.15))
    }

    // Back to front, so the near side sits on top of the far side.
    for p in points.sorted(by: { $0.depth < $1.depth }) {
        let d = (p.depth + 1) / 2                 // 0 = far side, 1 = near side
        dot(p.x, p.y, base * (0.55 + 0.45 * d), 0.3 + 0.7 * d)
    }

    // A bright core: the thing that is thinking.
    if detailed {
        dot(cx, cy, 34 * scale, 1.0)
        dot(cx, cy, 62 * scale, 0.18)
    } else {
        dot(cx, cy, 46 * scale, 1.0)
    }

    let cg = ctx.makeImage()!
    let rep = NSBitmapImageRep(cgImage: cg)
    rep.size = NSSize(width: size, height: size)
    return rep.representation(using: .png, properties: [:])!
}

let outPath = CommandLine.arguments.count > 1 ? CommandLine.arguments[1] : "AppIcon.icns"
let iconset = URL(fileURLWithPath: NSTemporaryDirectory())
    .appendingPathComponent("Jarvis.iconset")
try? FileManager.default.removeItem(at: iconset)
try! FileManager.default.createDirectory(at: iconset, withIntermediateDirectories: true)

for (base, scale) in [(16, 1), (16, 2), (32, 1), (32, 2), (128, 1), (128, 2),
                      (256, 1), (256, 2), (512, 1), (512, 2)] {
    let px = base * scale
    let name = scale == 1 ? "icon_\(base)x\(base).png" : "icon_\(base)x\(base)@2x.png"
    try! render(size: px).write(to: iconset.appendingPathComponent(name))
}

let p = Process()
p.executableURL = URL(fileURLWithPath: "/usr/bin/iconutil")
p.arguments = ["-c", "icns", iconset.path, "-o", outPath]
try! p.run()
p.waitUntilExit()
try? FileManager.default.removeItem(at: iconset)
print(p.terminationStatus == 0 ? "wrote \(outPath)" : "iconutil failed")
exit(p.terminationStatus)
